      "excerpts": {
        "original": {
          "quote": "В октябре 1805 года русские войска занимали села и города эрцгерцогства Австрийского, и еще новые полки приходили из России и, отягощая постоем жителей, располагались у крепости Браунау. В Браунау была главная квартира главнокомандующего Кутузова.",
          "language": "ru",
          "url": "https://ru.wikisource.org/wiki/%D0%92%D0%BE%D0%B9%D0%BD%D0%B0_%D0%B8_%D0%BC%D0%B8%D1%80_(%D0%A2%D0%BE%D0%BB%D1%81%D1%82%D0%BE%D0%B9)%2F%D0%A2%D0%BE%D0%BC_1#%D0%A7%D0%90%D0%A1%D0%A2%D0%AC_%D0%92%D0%A2%D0%9E%D0%A0%D0%90%D0%AF.",
          "attribution": "Лев Толстой · Война и мир · 1869",
          "rightsUrl": "https://ru.wikisource.org/wiki/Война_и_мир_(Толстой)",
          "type": "original"
        },
        "translations": {
          "en": {
            "quote": "In October, 1805, a Russian army was occupying the villages and towns of the Archduchy of Austria, and yet other regiments freshly arriving from Russia were settling near the fortress of Braunau and burdening the inhabitants on whom they were quartered. Braunau was the headquarters of the commander in chief, Kutúzov.",
            "language": "en",
            "url": "https://www.gutenberg.org/files/2600/2600-h/2600-h.htm#link2HCH0029",
            "attribution": "Louise and Aylmer Maude · historical English translation",
            "rightsUrl": "https://www.gutenberg.org/ebooks/2600",
            "type": "translation"
          },
          "fr": {
            "quote": "En octobre 1805, l’armée russe occupait les villes et les villages de l’archiduché d’Autriche, et de nouveaux régiments venus de la Russie, qui pesaient lourdement sur les habitants, se disposaient près de la forteresse de Braunau. Braunau était le quartier général du commandant en chef Koutouzov.",
            "language": "fr",
            "url": "https://fr.wikisource.org/wiki/Guerre_et_Paix_(trad._Bienstock)%2FII%2F01",
            "attribution": "J.-Wladimir Bienstock · traduction française · 1903–1904",
            "rightsUrl": "https://fr.wikisource.org/wiki/Guerre_et_Paix_(trad._Bienstock)",
            "type": "translation"
          }
        }
      },
