              "quote": "[…] Анна Павловна своих гостей, был теперь не Мортемар, а дипломат, приехавший из Берлина и привезший самые свежие подробности о пребывании государя Александра в Потсдаме и о том, как два высочайшие друга поклялись там в неразрывном союзе отстаивать правое дело против врага человеческого рода. Пьер был принят Анной Павловной с оттенком грусти, относившейся, очевидно, к свежей потере, постигшей молодого человека, к смерти графа Безухова (все постоянно считали долгом уверять Пьера, что он очень огорчен кончиною отца, которого он почти не знал), — и грусти точно такой же, как и та высочайшая грусть, которая выражалась […]",
