            "quote": "До половины дороги, как это всегда бывает, от Кременчуга до Киева, все мысли Ростова были еще назади — в эскадроне; но перевалившись за половину, он уже начал забывать тройку саврасых, своего вахмистра Дожойвейку, и беспокойно начал спрашивать себя о том, что́ и как он найдет в Отрадном. Чем ближе он подъезжал, тем сильнее, гораздо сильнее (как будто нравственное чувство было подчинено тому же закону притяжения обратно квадратам расстояний), он думал о своем доме; на последней перед Отрадным станции, дал ямщику три рубля на водку, и как мальчик задыхаясь вбежал на крыльцо дома.",
