      "placeText": [
        "Kutuzov’s council at Fili decides to abandon Moscow.",
        "Napoleon waits on Poklonnaya Hill for Moscow’s submission.",
        "The Rostovs prepare to leave and offer their carts to the wounded.",
        "Pierre takes refuge in Bazdeev’s house near Patriarch’s Ponds. No house address is asserted.",
        "French troops enter the Arbat as the occupation begins.",
        "The French column moves along Vozdvizhenka towards the Kremlin.",
        "Napoleon is at the Kremlin while fires spread through Moscow.",
        "The Rostov convoy stops at Mytishchi; Natasha finds the wounded Andrei."
      ],
