      "id": 17,
      "title": "Second Epilogue",
      "time": "",
      "setting": "History and freedom",
      "people": "",
      "text": "Tolstoy examines historical causation, power, freedom and necessity. This philosophical conclusion has no fictional scene itinerary.",
      "places": [],
