              "quote": "[…] он опять пошел убивать народ в Италии, Австрии и Пруссии. И там много убил. В России же был император Александр, который решился восстановить порядок в Европе и потому воевал с Наполеоном. Но в 7-м году он вдруг подружился с ним, а в 11-м опять поссорился, и опять они стали убивать много народу. И Наполеон привел 600 тысяч человек в Россию и завоевал Москву; а потом он вдруг убежал из Москвы, и тогда император Александр, с помощью советов Штейна и других, соединил Европу для ополчения против нарушителя ее спокойствия. Все союзники Наполеона сделались вдруг его врагами; и это ополчение пошло против […]",
